public.ca_union_set_statement_paid(uuid,.definition:
CREATE OR REPLACE FUNCTION public.ca_union_set_statement_paid(p_invoice_id uuid, p_paid boolean DEFAULT true, p_amount numeric DEFAULT NULL::numeric, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid      uuid := auth.uid();
  v_inv      settlement_invoices%ROWTYPE;
  v_union    uuid;
  v_owed     numeric;
  v_prev     numeric;
  v_add      numeric;
  v_total    numeric;
  v_status   text;
  v_payments jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'sign in required' USING ERRCODE = '42501';
  END IF;

  -- lock the row: two union admins clicking at once must not both read the
  -- same paid_total and each add their payment to it
  SELECT * INTO v_inv FROM settlement_invoices
   WHERE id = p_invoice_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'statement not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_inv.invoice_type <> 'union_weekly_squareup' THEN
    RAISE EXCEPTION 'not a weekly square-up statement' USING ERRCODE = '22023';
  END IF;

  -- Authority follows the invoice issuer, never the club's later membership.
  v_union := NULLIF(v_inv.breakdown->>'union_id','')::uuid;
  IF v_union IS NULL OR NOT ca_can_oversee_union(v_union) THEN
    RAISE EXCEPTION 'not authorized for this union' USING ERRCODE = '42501';
  END IF;

  IF v_inv.status = 'cancelled' THEN
    RAISE EXCEPTION 'this statement was cancelled' USING ERRCODE = '22023';
  END IF;

  -- the amount owed is an absolute: a statement where the union owes the club
  -- is settled by the same act of paying it, in the other direction
  -- ... less every credit note that adjusts it and is not cancelled
  -- (2026-11-15, audit G4), never below zero.
  v_owed     := GREATEST(round(abs(COALESCE(v_inv.net_amount, 0)) - COALESCE((
                  SELECT SUM(cn.net_amount) FROM settlement_invoices cn
                   WHERE cn.adjusts_invoice_id = v_inv.id
                     AND cn.invoice_type = 'union_weekly_credit_note'
                     AND cn.status IS DISTINCT FROM 'cancelled'), 0), 2), 0);
  v_prev     := COALESCE((v_inv.breakdown->>'paid_total')::numeric, 0);
  v_payments := COALESCE(v_inv.breakdown->'payments', '[]'::jsonb);

  IF p_paid IS NULL THEN
    RAISE EXCEPTION 'payment action is required' USING ERRCODE = '22023';
  END IF;
  IF v_inv.net_amount IS NULL OR EXISTS (
    SELECT 1 FROM unnest(ARRAY[v_inv.net_amount, v_prev]) n
    WHERE n::text IN ('NaN','Infinity','-Infinity') OR n <> round(n,2)
  ) OR v_prev < 0 THEN
    RAISE EXCEPTION 'statement amounts must be finite whole cents' USING ERRCODE = '22023';
  END IF;
  IF p_amount IS NOT NULL AND
    (p_amount::text IN ('NaN','Infinity','-Infinity') OR p_amount <= 0 OR p_amount <> round(p_amount,2)) THEN
    RAISE EXCEPTION 'payment amount must be positive finite whole cents' USING ERRCODE = '22023';
  END IF;

  IF p_paid THEN
    -- no amount given means "settled in full", which is the common case and
    -- should not require the caller to restate a number the row already holds
    v_add   := COALESCE(p_amount, GREATEST(v_owed - v_prev, 0));
    IF v_add <= 0 AND v_prev >= v_owed THEN
      RETURN jsonb_build_object(
        'success', true, 'already_settled', true,
        'invoice_id', p_invoice_id, 'status', v_inv.status,
        'paid_total', v_prev, 'owed', v_owed);
    END IF;
    v_total := round(v_prev + GREATEST(v_add, 0), 2);
    -- A short payment remains outstanding down to the last cent.
    v_status := CASE WHEN v_total >= v_owed THEN 'paid'
      WHEN v_inv.status = 'paid' THEN 'generated' ELSE v_inv.status END;
    v_payments := v_payments || jsonb_build_object(
      'amount', round(GREATEST(v_add, 0), 2),
      'at', now(),
      'by', v_uid,
      'note', NULLIF(btrim(COALESCE(p_note, '')), ''));
  ELSE
    -- reopening: mistakes get made, and a statement that can only ever move
    -- one way turns a misclick into a permanent falsehood in the record. The
    -- payment history is kept, with the reversal appended to it.
    v_total  := 0;
    v_status := 'generated';
    v_payments := v_payments || jsonb_build_object(
      'amount', 0, 'reversal', true, 'at', now(), 'by', v_uid,
      'note', NULLIF(btrim(COALESCE(p_note, '')), ''));
  END IF;

  UPDATE settlement_invoices
     SET status     = v_status,
         updated_at = now(),
         breakdown  = COALESCE(breakdown, '{}'::jsonb) || jsonb_build_object(
           'paid_total', v_total,
           'paid_at',    CASE WHEN v_status = 'paid' THEN now() ELSE NULL END,
           'paid_by',    CASE WHEN v_status = 'paid' THEN v_uid  ELSE NULL END,
           'payments',   v_payments)
   WHERE id = p_invoice_id;

  RETURN jsonb_build_object(
    'success', true,
    'invoice_id', p_invoice_id,
    'status', v_status,
    'paid_total', v_total,
    'owed', v_owed,
    'fully_settled', (v_status = 'paid'));
END;
$function$

public.fn_deliver_accounting_invoice(uui.definition:
CREATE OR REPLACE FUNCTION public.fn_deliver_accounting_invoice(p_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_variable
DECLARE inv public.settlement_invoices%ROWTYPE; sender uuid; issuer_name text; recipient_name text;
 issuer_kind text; issuer_id uuid; recipient_id uuid; scope_id uuid; page_id uuid; users uuid[]; issuer_users uuid[]; recipient_users uuid[];
 person uuid; conv uuid; msg uuid; note uuid; body text; meta jsonb; count_sent int:=0; n int; line record; cashier public.accounting_cashier_events%ROWTYPE; cashier_payload jsonb; correction public.accounting_correction_documents%ROWTYPE; correction_payload jsonb; credit_change public.accounting_credit_change_documents_v1%ROWTYPE; credit_operation public.accounting_credit_reduction_operations_v1%ROWTYPE; credit_payload jsonb;
BEGIN
 SELECT * INTO inv FROM public.settlement_invoices WHERE id=p_invoice_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'accounting_invoice_missing' USING ERRCODE='23514'; END IF;
 IF public.fn_accounting_correction_is_unverified(inv.id)
 THEN RAISE EXCEPTION 'historical_correction_document_unverified' USING ERRCODE='23514';END IF;
 IF inv.net_amount IS NULL OR inv.net_amount::text IN('NaN','Infinity','-Infinity') OR inv.net_amount<>round(inv.net_amount,2)
 THEN RAISE EXCEPTION 'invalid_invoice_amount' USING ERRCODE='23514'; END IF;
 -- Owner rule (2026-10-15): only cashout documents reach the messenger (the player's request
 -- reaches their agent, the approval reaches the player). Every other invoice is recorded in
 -- transaction history only and marked delivered so the weekly close is satisfied.
 -- Owner rule (2026-11-14) supersedes it for the union's weekly statements:
 -- "THE UNION IS ... SENDING INVOICES TO THE CLUBS WITHIN THE UNION". A union
 -- square-up or credit note reaches the club and the union like a cashout
 -- document; the union's own hub row is a statement to itself, record-only.
 IF inv.invoice_type IS DISTINCT FROM 'cashier_cashout'
    AND NOT (inv.invoice_type IN('union_weekly_squareup','union_weekly_credit_note')
             AND inv.club_id IS DISTINCT FROM NULLIF(inv.breakdown->>'union_id','')::uuid) THEN
  IF inv.invoice_number IS NULL THEN
   UPDATE public.settlement_invoices SET invoice_number=public.fn_accounting_next_invoice_number() WHERE id=inv.id RETURNING invoice_number INTO inv.invoice_number;
  END IF;
  UPDATE public.settlement_invoices SET message_sent=true,message_sent_at=COALESCE(message_sent_at,now()) WHERE id=inv.id;
  RETURN jsonb_build_object('success',true,'invoice_id',inv.id,'delivered',0,'new_deliveries',0);
 END IF;
 issuer_kind:=inv.from_entity_type; issuer_id:=inv.from_entity_id::uuid; recipient_id:=inv.to_entity_id::uuid;
 scope_id:=COALESCE(inv.club_id,issuer_id);
 IF inv.invoice_type='credit_limit_change' THEN
  credit_payload:=public.fn_accounting_credit_change_contract_v1(inv.id);
  SELECT * INTO STRICT credit_change FROM public.accounting_credit_change_documents_v1 WHERE invoice_id=inv.id;
  SELECT * INTO STRICT credit_operation FROM public.accounting_credit_reduction_operations_v1 WHERE id=credit_change.operation_receipt_id;
  users:=credit_change.audience_user_ids;sender:=credit_operation.actor_user_id;
  issuer_kind:='club';issuer_id:=credit_operation.club_id;scope_id:=credit_operation.club_id;
  issuer_name:=credit_change.issuer_name;recipient_name:=credit_change.recipient_name;
 ELSIF inv.invoice_type='accounting_correction' THEN
  SELECT * INTO correction FROM public.accounting_correction_documents WHERE invoice_id=inv.id;
  IF NOT FOUND OR correction.club_id IS DISTINCT FROM inv.club_id OR correction.source_ledger_id IS DISTINCT FROM inv.source_ledger_id
   OR correction.amount IS DISTINCT FROM inv.net_amount OR inv.breakdown IS DISTINCT FROM jsonb_build_object('category','correction','correction',public.fn_accounting_correction_payload(correction))
   OR inv.status IS DISTINCT FROM 'generated' OR inv.chips_transferred IS DISTINCT FROM false OR inv.transferred_at IS NOT NULL OR inv.due_at IS NOT NULL
  THEN RAISE EXCEPTION 'correction_document_delivery_source_unverified' USING ERRCODE='23514';END IF;
  users:=correction.audience_user_ids;sender:=correction.issuer_representative_id;
  issuer_kind:=correction.issuer_type;issuer_id:=correction.issuer_id;scope_id:=correction.club_id;
  issuer_name:=correction.issuer_name;recipient_name:=correction.payee_name;correction_payload:=public.fn_accounting_correction_payload(correction);
 ELSIF inv.invoice_type='cashier_cashout' THEN
  SELECT * INTO cashier FROM public.accounting_cashier_events WHERE invoice_id=inv.id;
  IF NOT FOUND OR cashier.club_id IS DISTINCT FROM inv.club_id OR cashier.source_ledger_id IS DISTINCT FROM inv.source_ledger_id
    OR cashier.amount IS DISTINCT FROM inv.net_amount OR inv.breakdown->'cashier' IS DISTINCT FROM public.fn_cashier_event_payload(cashier)
  THEN RAISE EXCEPTION 'cashier_delivery_event_missing' USING ERRCODE='23514';END IF;
  users:=cashier.audience_user_ids;sender:=cashier.issuer_representative_id;
  issuer_kind:='club';issuer_id:=cashier.club_id;scope_id:=cashier.club_id;
  issuer_name:=cashier.issuer_name;recipient_name:=cashier.player_name;
  cashier_payload:=public.fn_cashier_event_payload(cashier);
 ELSE
 SELECT array_agg(user_id ORDER BY user_id) INTO issuer_users FROM public.fn_accounting_invoice_party_users(inv.from_entity_type,issuer_id);
 SELECT array_agg(user_id ORDER BY user_id) INTO recipient_users FROM public.fn_accounting_invoice_party_users(inv.to_entity_type,recipient_id);
 IF COALESCE(cardinality(issuer_users),0)=0 OR COALESCE(cardinality(recipient_users),0)=0
 THEN RAISE EXCEPTION 'accounting_invoice_recipient_missing' USING ERRCODE='23514'; END IF;
 SELECT array_agg(DISTINCT x ORDER BY x) INTO users FROM unnest(issuer_users||recipient_users) x;
 -- Club senders receive one weekly summary; individual payees still get their receipt immediately.
 IF inv.from_entity_type='club' AND inv.to_entity_type IN('agent','player')
    AND inv.source_ledger_id IS NOT NULL AND inv.breakdown->>'category' IN('rakeback','commission') THEN
   users:=recipient_users;
 END IF;
 IF inv.invoice_type IN('union_weekly_squareup','union_weekly_credit_note') THEN
   issuer_kind:='union';issuer_id:=(inv.breakdown->>'union_id')::uuid;
 END IF;
 sender:=CASE WHEN issuer_kind='club' THEN (SELECT owner_id FROM public.clubs WHERE id=issuer_id)
              WHEN issuer_kind='union' THEN (SELECT owner_id FROM public.unions WHERE id=issuer_id)
              ELSE issuer_id END;
 IF sender IS NULL OR NOT sender=ANY(issuer_users||recipient_users) THEN RAISE EXCEPTION 'accounting_invoice_sender_missing' USING ERRCODE='23514'; END IF;
 issuer_name:=CASE WHEN issuer_kind='club' THEN (SELECT name FROM public.clubs WHERE id=issuer_id)
                   WHEN issuer_kind='union' THEN (SELECT name FROM public.unions WHERE id=issuer_id)
                   ELSE (SELECT username FROM public.profiles WHERE id=issuer_id) END;
 recipient_name:=CASE WHEN inv.to_entity_type='club' THEN (SELECT name FROM public.clubs WHERE id=recipient_id)
                      WHEN inv.to_entity_type='union' THEN (SELECT name FROM public.unions WHERE id=recipient_id)
                      ELSE (SELECT username FROM public.profiles WHERE id=recipient_id) END;
 END IF;
 IF inv.invoice_number IS NULL THEN
   UPDATE public.settlement_invoices SET invoice_number=public.fn_accounting_next_invoice_number() WHERE id=inv.id RETURNING invoice_number INTO inv.invoice_number;
 END IF;
 IF inv.invoice_type IN('union_weekly_squareup','union_weekly_credit_note') THEN recipient_name:=(SELECT name FROM public.clubs WHERE id=inv.club_id); END IF;
 body:=CASE WHEN inv.invoice_type='club_weekly_accounting' THEN 'Weekly Club Statement ' ELSE 'Invoice ' END||inv.invoice_number||E'\nIssued By: '||COALESCE(issuer_name,inv.from_entity_type)||E'\nFor: '||COALESCE(recipient_name,inv.to_entity_type)
  ||E'\nDirection: '||initcap(inv.from_entity_type)||' To '||initcap(inv.to_entity_type)
  ||E'\nAmount: '||to_char(abs(inv.net_amount),'FM999,999,999,999,990.00')||' Chips'
  ||E'\nStatus: '||initcap(inv.status)
  ||CASE WHEN inv.chips_transferred THEN E'\nTransfer Recorded: '||COALESCE(inv.transferred_at,inv.created_at)::text ELSE '' END
  ||CASE WHEN inv.due_at IS NOT NULL THEN E'\nDue: '||to_char(inv.due_at AT TIME ZONE 'America/Chicago','YYYY-MM-DD HH24:MI')||' Chicago Time' ELSE '' END
  ||CASE WHEN inv.breakdown ? 'period_start' THEN E'\nPeriod: '||(inv.breakdown->>'period_start')||' To '||COALESCE(inv.breakdown->>'period_end','') ELSE '' END
  ||CASE WHEN inv.notes IS NOT NULL THEN E'\n'||inv.notes ELSE '' END;
 FOR line IN SELECT key,value FROM jsonb_each_text(COALESCE(inv.breakdown,'{}'))
   WHERE key IN('rake_generated','rakeback_due','union_fee_kept','players_won','settled_in_chips','eco_amount','presettled','rake_earned','union_rake_earned','private_rake_earned','private_rake_banked','total_rake_funding','rake_received','paid_super_agents','paid_agents','paid_sub_agents','paid_players','total_paid_by_club','retained_by_club','downstream_redistributed','downstream_paid_super_agents','downstream_paid_agents','downstream_paid_sub_agents','downstream_paid_players') ORDER BY key
 LOOP
   IF line.value IS NOT NULL THEN body:=body||E'\n'||initcap(replace(line.key,'_',' '))||': '||to_char(line.value::numeric,'FM999,999,999,999,990.00'); END IF;
 END LOOP;
 IF inv.invoice_type IN('union_weekly_squareup','union_weekly_credit_note') THEN body:=smarter_private.union_weekly_invoice_body(inv.id);
 ELSIF inv.invoice_type='credit_limit_change' THEN body:=public.fn_accounting_credit_change_body_v1(credit_change.id,inv.invoice_number);
 ELSIF inv.invoice_type='cashier_cashout' THEN body:=public.fn_cashier_document_body(cashier.id,inv.invoice_number);
 ELSIF inv.invoice_type='accounting_correction' THEN body:=public.fn_accounting_correction_document_body(correction.id,inv.invoice_number);END IF;
 meta:=jsonb_build_object('kind','accounting_invoice' ,'invoice_id',inv.id,'invoice_number',inv.invoice_number,
   'club_id',inv.club_id,'source_ledger_id',inv.source_ledger_id,'source_credit_invoice_id',inv.source_credit_invoice_id,
   'source_credit_payment_id',inv.source_credit_payment_id,'amount',inv.net_amount,'currency','CHIPS','conversationId',NULL,'status',inv.status,
   'invoice_type',inv.invoice_type,'from_entity_type',inv.from_entity_type,'from_entity_id',inv.from_entity_id,
   'to_entity_type',inv.to_entity_type,'to_entity_id',inv.to_entity_id,'lines',inv.breakdown-ARRAY['source_ledger_ids','private_bank_ledger_ids','standalone_bank_ledger_ids','standalone_bank_mint_ids']);
 IF inv.invoice_type='credit_limit_change' THEN meta:=meta||jsonb_build_object('credit_change',credit_payload);
 ELSIF inv.invoice_type='cashier_cashout' THEN meta:=meta||jsonb_build_object('cashier',cashier_payload);
 ELSIF inv.invoice_type='accounting_correction' THEN meta:=meta||jsonb_build_object('correction',correction_payload);END IF;
 SELECT id INTO page_id FROM public.social_pages WHERE linked_entity_id=scope_id::text AND linked_entity_type='club' ORDER BY id LIMIT 1;
 FOREACH person IN ARRAY users LOOP
   IF EXISTS(SELECT 1 FROM public.accounting_invoice_deliveries d WHERE d.invoice_id=inv.id AND d.recipient_id=person) THEN CONTINUE; END IF;
   -- One private accounting conversation per issuer, sender, scope and recipient.
   PERFORM pg_advisory_xact_lock(hashtextextended('accounting_conversation:'||scope_id::text||':'||issuer_id::text||':'||sender::text||':'||person::text,0));
   SELECT conversation_id INTO conv FROM public.accounting_conversations c
    WHERE c.scope_id=scope_id AND c.issuer_type=issuer_kind AND c.issuer_id=issuer_id AND c.sender_id=sender AND c.recipient_id=person;
   IF conv IS NULL THEN
     INSERT INTO public.social_conversations(is_group,group_name,context_entity_id,context_entity_type)
      VALUES(true,COALESCE(issuer_name,'Account')||' Accounting',page_id,CASE WHEN page_id IS NULL THEN NULL ELSE 'club' END) RETURNING id INTO conv;
     INSERT INTO public.social_conversation_participants(conversation_id,user_id,context_entity_id,context_entity_type)
      SELECT conv,x,page_id,CASE WHEN page_id IS NULL THEN NULL ELSE 'club' END FROM (SELECT DISTINCT unnest(ARRAY[sender,person]) AS x) members;
     INSERT INTO public.accounting_conversations(scope_id,issuer_type,issuer_id,sender_id,recipient_id,conversation_id)
      VALUES(scope_id,issuer_kind,issuer_id,sender,person,conv);
   END IF;
   -- Refuse a conversation whose audience changed instead of leaking invoices.
   IF EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id<>ALL(ARRAY[sender,person]))
      OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id=person)
      OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants WHERE conversation_id=conv AND user_id=sender)
   THEN RAISE EXCEPTION 'accounting_conversation_audience_changed' USING ERRCODE='23514'; END IF;
   meta:=meta||jsonb_build_object('conversation_id',conv,'conversationId',conv);
   INSERT INTO public.social_messages(conversation_id,sender_id,content,message_type,media_metadata)
    VALUES(conv,sender,body,'invoice',meta) RETURNING id INTO msg;
   UPDATE public.social_conversations SET last_message_at=now(),last_message_preview=left(body,100),updated_at=now() WHERE id=conv;
   meta:=meta||jsonb_build_object('conversation_id',conv,'conversationId',conv);
   INSERT INTO public.notifications(user_id,type,title,message,data,read,action_url,metadata)
    VALUES(person,CASE WHEN inv.chips_transferred AND inv.invoice_type NOT IN('credit_limit_change','accounting_correction','cashier_cashout') THEN 'accounting_invoice_detail' ELSE 'accounting_invoice' END,CASE WHEN inv.invoice_type='cashier_cashout' THEN public.fn_cashier_notice_copy(cashier,person,inv.invoice_number)->>'title' ELSE CASE WHEN inv.invoice_type='credit_limit_change' THEN 'Credit Line Updated · ' WHEN inv.invoice_type='accounting_correction' THEN 'Correction Recorded · ' WHEN inv.invoice_type='cashier_cashout' THEN CASE cashier.event_kind WHEN 'hold' THEN 'Chips Held · ' WHEN 'approval' THEN 'Cashout Approved · ' ELSE 'Chips Returned · ' END WHEN inv.invoice_type='club_weekly_accounting' THEN 'Weekly Club Statement ' ELSE 'Invoice ' END||inv.invoice_number END,
     CASE WHEN inv.invoice_type='cashier_cashout' THEN public.fn_cashier_notice_copy(cashier,person,inv.invoice_number)->>'message' ELSE CASE WHEN inv.invoice_type='credit_limit_change' THEN 'Credit capacity reduced: '||to_char(inv.net_amount,'FM999,999,999,999,990.00')||'. No payment due.'
      ELSE CASE WHEN inv.invoice_type='accounting_correction' THEN 'Correction Recorded: ' WHEN inv.invoice_type='cashier_cashout' THEN CASE cashier.event_kind WHEN 'hold' THEN 'Chips Held: ' WHEN 'approval' THEN 'Cashout Approved: ' ELSE 'Chips Returned: ' END WHEN inv.chips_transferred AND inv.breakdown->>'category'='rakeback' THEN 'Rakeback Transfer Recorded: ' WHEN inv.chips_transferred AND inv.breakdown->>'category'='commission' THEN 'Commission Transfer Recorded: ' WHEN inv.chips_transferred THEN 'Transfer Recorded: ' ELSE 'Invoice Issued: ' END||to_char(abs(inv.net_amount),'FM999,999,999,999,990.00')||' Chips' END END,
     meta,(inv.chips_transferred AND inv.invoice_type NOT IN('credit_limit_change','accounting_correction','cashier_cashout')),'/hub/messenger?conversation='||conv::text,meta) RETURNING id INTO note;
   INSERT INTO public.accounting_invoice_deliveries(invoice_id,recipient_id,message_id,notification_id) VALUES(inv.id,person,msg,note);
   count_sent:=count_sent+1;
 END LOOP;
 SELECT count(*) INTO n FROM public.accounting_invoice_deliveries WHERE invoice_id=inv.id;
 -- A union statement is marked sent only when delivered (2026-11-15, audit G3):
 -- with no recipient reached it stays unsent, never "Delivered" to nobody.
 UPDATE public.settlement_invoices SET message_sent=true,message_sent_at=COALESCE(message_sent_at,now()) WHERE id=inv.id
   AND (n>0 OR inv.invoice_type NOT IN('union_weekly_squareup','union_weekly_credit_note'));
 RETURN jsonb_build_object('success',true,'invoice_id',inv.id,'delivered',n,'new_deliveries',count_sent);
END $function$

public.fn_next_invoice_number(uuid,times.definition:
CREATE OR REPLACE FUNCTION public.fn_next_invoice_number(p_union_id uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year   int := EXTRACT(year FROM (p_at AT TIME ZONE 'America/Los_Angeles'))::int;
  v_seq    bigint;
  v_prefix text;
BEGIN
  SELECT upper(left(regexp_replace(COALESCE(u.slug, u.name, 'union'), '[^a-zA-Z0-9]', '', 'g'), 6))
    INTO v_prefix
    FROM unions u WHERE u.id = p_union_id;
  IF v_prefix IS NULL OR v_prefix = '' THEN
    RAISE EXCEPTION 'cannot derive an invoice prefix for union %', p_union_id;
  END IF;

  LOOP
    UPDATE union_invoice_counters
       SET next_seq = next_seq + 1, updated_at = now()
     WHERE union_id = p_union_id AND year = v_year
     RETURNING next_seq - 1 INTO v_seq;
    EXIT WHEN FOUND;

    BEGIN
      INSERT INTO union_invoice_counters (union_id, year, next_seq)
      VALUES (p_union_id, v_year, 2);
      v_seq := 1;
      EXIT;
    EXCEPTION WHEN unique_violation THEN
      -- Another session created the row first; go round and take the update path.
    END;
  END LOOP;

  RETURN v_prefix || '-' || v_year::text || '-' || lpad(v_seq::text, 6, '0');
END $function$

public.fn_union_issue_credit_note(uuid,n.definition:
CREATE OR REPLACE FUNCTION public.fn_union_issue_credit_note(p_invoice_id uuid, p_amount numeric, p_reason text, p_notify boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_orig      settlement_invoices%ROWTYPE;
  v_union_id  uuid;
  v_union_name text;
  v_club_name text;
  v_credited  numeric;
  v_remaining numeric;
  v_number    text;
  v_new_id    uuid;
  v_msg       jsonb;
  v_body      text;
BEGIN
  SELECT * INTO v_orig FROM settlement_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF v_orig.id IS NULL THEN
    RAISE EXCEPTION 'invoice not found';
  END IF;

  v_union_id := (v_orig.breakdown->>'union_id')::uuid;

  -- WHO IS CALLING, before anything that would describe the document.
  IF auth.uid() IS NOT NULL
     AND (v_union_id IS NULL
          OR (NOT EXISTS (SELECT 1 FROM unions u WHERE u.id = v_union_id AND u.owner_id = auth.uid())
              AND NOT EXISTS (SELECT 1 FROM union_admins ua WHERE ua.union_id = v_union_id AND ua.user_id = auth.uid())
              AND NOT COALESCE(public.fn_is_platform_admin(), false))) THEN
    RAISE EXCEPTION 'not_authorised';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'a credit note must be for a positive amount, got %', p_amount;
  END IF;
  IF COALESCE(btrim(p_reason), '') = '' THEN
    RAISE EXCEPTION 'a credit note must carry a reason';
  END IF;
  IF v_orig.invoice_type <> 'union_weekly_squareup' THEN
    RAISE EXCEPTION 'only a weekly square-up can be credited, this is %', v_orig.invoice_type;
  END IF;
  IF v_union_id IS NULL THEN
    RAISE EXCEPTION 'invoice % carries no union_id in its breakdown', p_invoice_id;
  END IF;

  SELECT COALESCE(SUM(net_amount), 0) INTO v_credited
    FROM settlement_invoices
   WHERE adjusts_invoice_id = p_invoice_id
     AND invoice_type = 'union_weekly_credit_note';

  v_remaining := round(v_orig.net_amount - v_credited, 2);
  IF p_amount > v_remaining + 0.005 THEN
    RAISE EXCEPTION
      'credit note of % exceeds what is left on invoice % (net %, already credited %, remaining %)',
      p_amount, COALESCE(v_orig.invoice_number, v_orig.id::text),
      v_orig.net_amount, v_credited, v_remaining;
  END IF;

  SELECT u.name INTO v_union_name FROM unions u WHERE u.id = v_union_id;
  SELECT c.name INTO v_club_name FROM clubs c WHERE c.id = v_orig.club_id;
  v_number := public.fn_next_invoice_number(v_union_id, now());

  INSERT INTO settlement_invoices (
    club_id, period_id, invoice_type, invoice_number, adjusts_invoice_id,
    from_entity_type, from_entity_id, to_entity_type, to_entity_id,
    gross_amount, net_amount, deductions, breakdown, status,
    chips_transferred, due_at, notes)
  VALUES (
    v_orig.club_id, v_orig.period_id, 'union_weekly_credit_note', v_number, v_orig.id,
    v_orig.to_entity_type,   v_orig.to_entity_id,
    v_orig.from_entity_type, v_orig.from_entity_id,
    p_amount, p_amount, 0,
    jsonb_build_object(
      'union_id', v_union_id, 'union_name', v_union_name,
      'club_id', v_orig.club_id, 'club_name', v_club_name,
      'credit_note_for', COALESCE(v_orig.invoice_number, v_orig.id::text),
      'original_invoice_id', v_orig.id,
      'original_net_amount', v_orig.net_amount,
      'previously_credited', v_credited,
      'remaining_before_this', v_remaining,
      'reason', p_reason,
      'period_start', v_orig.breakdown->>'period_start',
      'period_end', v_orig.breakdown->>'period_end',
      'issued_at', now()),
    'generated', false, v_orig.due_at,
    'Credit note against ' || COALESCE(v_orig.invoice_number, v_orig.id::text) || '. ' || p_reason)
  RETURNING id INTO v_new_id;

  IF p_notify THEN
    v_body :=
      COALESCE(v_union_name, 'Union') || ' credit note ' || v_number || E'\n'
      || 'Against statement ' || COALESCE(v_orig.invoice_number, v_orig.id::text) || E'\n\n'
      || 'Credit amount       ' || to_char(p_amount, 'FM999,999,999,990.00') || E'\n'
      || 'Original statement  ' || to_char(v_orig.net_amount, 'FM999,999,999,990.00') || E'\n'
      || CASE WHEN v_credited > 0
              THEN 'Previously credited ' || to_char(v_credited, 'FM999,999,999,990.00') || E'\n'
              ELSE '' END
      || 'Remaining after     ' || to_char(round(v_remaining - p_amount, 2), 'FM999,999,999,990.00')
      || E'\n\n'
      || 'Reason: ' || p_reason || E'\n\n'
      || 'The original statement is unchanged. This credit note adjusts it.';

    v_msg := fn_union_send_club_message(
      v_union_id, v_orig.club_id, v_body,
      jsonb_build_object(
        'kind', 'union_credit_note',
        'credit_note_id', v_new_id,
        'credit_note_number', v_number,
        'adjusts_invoice_id', v_orig.id,
        'adjusts_invoice_number', v_orig.invoice_number,
        'amount', p_amount,
        'reason', p_reason),
      'invoice');

    IF COALESCE((v_msg->>'delivered')::int, 0) > 0 THEN
      UPDATE settlement_invoices
         SET message_sent = true, message_sent_at = now()
       WHERE id = v_new_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'credit_note_id', v_new_id,
    'credit_note_number', v_number,
    'adjusts', COALESCE(v_orig.invoice_number, v_orig.id::text),
    'amount', p_amount,
    'original_net', v_orig.net_amount,
    'total_credited_now', round(v_credited + p_amount, 2),
    'remaining_after', round(v_remaining - p_amount, 2),
    'delivered', COALESCE((v_msg->>'delivered')::int, 0));
END $function$

public.fn_union_send_club_message(uuid,u.definition:
CREATE OR REPLACE FUNCTION public.fn_union_send_club_message(p_union_id uuid, p_club_id uuid, p_content text, p_metadata jsonb DEFAULT '{}'::jsonb, p_message_type text DEFAULT 'text'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sender      uuid;
  v_union_name  text;
  v_union_page  uuid;
  v_club_page   uuid;
  v_conv        uuid;
  v_title       text;
  v_msg_id      uuid;
  v_recipients  int := 0;
  r             record;
BEGIN
  -- Compatibility for existing invoice and credit-note callers. Reminders
  -- retain their distinct message, while issued documents use one delivery receipt.
  IF p_metadata->>'kind' IN ('union_invoice','union_credit_note') THEN
    IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR NOT public.fn_is_union_overseer(p_union_id,auth.uid())) THEN
      RAISE EXCEPTION 'not_authorised' USING ERRCODE='42501';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM public.settlement_invoices si
      WHERE si.id=COALESCE(p_metadata->>'invoice_id',p_metadata->>'credit_note_id')::uuid
        AND si.club_id=p_club_id AND (si.breakdown->>'union_id')::uuid=p_union_id) THEN
      RAISE EXCEPTION 'accounting_invoice_scope_mismatch' USING ERRCODE='42501';
    END IF;
    RETURN public.fn_deliver_accounting_invoice(COALESCE(p_metadata->>'invoice_id',p_metadata->>'credit_note_id')::uuid);
  END IF;
  SELECT u.owner_id, u.name INTO v_sender, v_union_name
    FROM unions u WHERE u.id = p_union_id;
  IF v_sender IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'union has no owner to send as');
  END IF;

  SELECT sp.id INTO v_union_page FROM social_pages sp
   WHERE sp.linked_entity_id = p_union_id::text AND sp.linked_entity_type = 'club' LIMIT 1;
  SELECT sp.id INTO v_club_page FROM social_pages sp
   WHERE sp.linked_entity_id = p_club_id::text AND sp.linked_entity_type = 'club' LIMIT 1;

  v_title := COALESCE(v_union_name, 'Union') || ' Statements';

  SELECT c.id INTO v_conv
    FROM social_conversations c
   WHERE c.is_group = true
     AND c.group_name = v_title
     AND c.context_entity_id IS NOT DISTINCT FROM v_club_page
   ORDER BY c.created_at ASC
   LIMIT 1;

  IF v_conv IS NULL THEN
    INSERT INTO social_conversations (is_group, group_name, context_entity_id, context_entity_type)
    VALUES (true, v_title, v_club_page, CASE WHEN v_club_page IS NULL THEN NULL ELSE 'club' END)
    RETURNING id INTO v_conv;
  END IF;

  -- RECIPIENTS FIRST, seated under the CLUB identity.
  FOR r IN
    SELECT DISTINCT x.uid
      FROM (
        SELECT c.owner_id AS uid FROM clubs c
         WHERE c.id = p_club_id AND c.owner_id IS NOT NULL
        UNION
        SELECT cm.user_id FROM club_members cm
         WHERE cm.club_id = p_club_id
           AND cm.role IN ('owner','co_owner','admin')
           AND COALESCE(cm.status,'active') NOT IN ('banned','suspended')
      ) x
     WHERE x.uid IS NOT NULL
       AND EXISTS (SELECT 1 FROM profiles pr WHERE pr.id = x.uid)
  LOOP
    INSERT INTO social_conversation_participants
      (conversation_id, user_id, context_entity_id, context_entity_type)
    VALUES (v_conv, r.uid, v_club_page,
            CASE WHEN v_club_page IS NULL THEN NULL ELSE 'club' END)
    ON CONFLICT (conversation_id, user_id) DO NOTHING;
    v_recipients := v_recipients + 1;
  END LOOP;

  IF v_recipients = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'club has no owner or admin with a profile',
                              'conversation_id', v_conv);
  END IF;

  -- The union owner joins under the UNION identity only if they are not
  -- already seated as a club recipient (one row per user is enforced).
  INSERT INTO social_conversation_participants
    (conversation_id, user_id, context_entity_id, context_entity_type)
  VALUES (v_conv, v_sender, v_union_page,
          CASE WHEN v_union_page IS NULL THEN NULL ELSE 'club' END)
  ON CONFLICT (conversation_id, user_id) DO NOTHING;

  INSERT INTO social_messages (conversation_id, sender_id, content, message_type, media_metadata)
  VALUES (v_conv, v_sender, p_content,
          COALESCE(NULLIF(p_message_type, ''), 'text'),
          CASE WHEN p_metadata = '{}'::jsonb OR p_metadata IS NULL THEN NULL ELSE p_metadata END)
  RETURNING id INTO v_msg_id;

  UPDATE social_conversations
     SET last_message_at = now(),
         last_message_preview = left(regexp_replace(p_content, E'\\s+', ' ', 'g'), 100),
         updated_at = now()
   WHERE id = v_conv;

  RETURN jsonb_build_object('success', true, 'delivered', v_recipients,
                            'conversation_id', v_conv, 'message_id', v_msg_id,
                            'club_page', v_club_page, 'union_page', v_union_page);
END;
$function$
